{
  "chapter_plan": {
    "thesis": "可见光消色差超构透镜在单界面局部相位调控假设下存在不可逾越的理论性能天花板。带宽与视场（FOV）的联合性能受限于延迟-带宽积，且由于有限孔径导致的群延迟需求非单调性，带宽随FOV的增加呈现饱和趋势而非线性恶化；同时，高数值孔径（NA）下单界面固有的几何像差将有效成像视场严格限制在微米量级。这两重物理约束共同确立了单层结构无法同时实现大带宽与大视场的根本边界。",
    "reader_objective": "读者应理解：(1) 色散工程消色差金属透镜的带宽上限由最大群延迟范围决定，且存在随FOV增加的饱和现象；(2) 单界面几何像差对高NA系统的视场限制是独立于色散的硬性约束；(3) 现有实验器件的性能瓶颈主要源于工艺和材料损耗，尚未触及这些理论物理极限。",
    "units": [
      {
        "unit_id": "U1",
        "substantive_point": "建立基于局部相互作用假设的延迟-带宽积基本物理约束，推导最大可用带宽与所需群延迟范围的定量关系。",
        "ordered_development": "首先确立理论基础，将超构原子建模为一维延迟线，引入延迟-带宽积极限公式。随后阐述为了实现消色差聚焦，透镜必须在空间上提供特定的群延迟分布以补偿不同频率的光程差。最后推导出最大可用带宽与透镜面上所需的最大群延迟跨度成反比的核心结论。",
        "paragraph_briefs": [
          {
            "point": "确立局部超表面的延迟-带宽积极限模型。",
            "development": "引用P0002中的通用界限，将每个超构原子视为一维延迟线，说明其能实现的群延迟范围受限于物理结构的带宽限制（如Miller界限）。指出为了实现宽带消色差操作，元原子必须提供恒定的群延迟轮廓。",
            "source_handles": ["P0002"]
          },
          {
            "point": "推导理想消色差聚焦所需的群延迟空间分布。",
            "development": "分析理想消色差聚焦所需的相位函数，它由线性梯度（波前偏转）和双曲线径向剖面（聚焦）叠加而成。通过对频率求导得到群延迟分布 $t_g(r, \\alpha)$，阐明该分布决定了每个位置需要提供的延迟量。",
            "source_handles": ["P0002"]
          },
          {
            "point": "建立最大可用带宽与最大群延迟跨度的反比关系。",
            "development": "定义整个工作视场内的最大群延迟范围 $\\Delta T_{max}$（即中心与边缘的最大延迟差值）。根据延迟-带宽积原理，推导出最大可用带宽 $\\Delta \\omega \\leq \\kappa / \\Delta T_{max}$，明确指出任何试图扩大带宽的努力都必须以减小所需的群延迟动态范围为前提。",
            "source_handles": ["P0002"]
          }
        ],
        "conditions_and_limits": "该推导严格依赖于‘局部相互作用’假设，即元原子间的近场耦合可忽略。常数 $\\kappa$ 取决于材料对比度和结构长度，代表了特定物理实现的上限。",
        "transition": "明确了带宽与群延迟范围的定量关系后，下一章需进一步分析在有限孔径下，这个关键的群延迟范围如何随视场角变化，从而揭示带宽饱和的物理根源。"
      },
      {
        "unit_id": "U2",
        "substantive_point": "揭示有限孔径金属透镜上群延迟需求的非单调性及其导致的带宽饱和现象。",
        "ordered_development": "分析有限孔径效应对群延迟分布的影响，论证所需总相位范围并不随入射角单调增加。解释掠射角附近相位需求反而减小的几何原因，确定最大群延迟范围出现在特定中间角度 $\\alpha^*$。基于此，阐述当FOV超过临界值后，带宽下限不再收紧并趋于饱和的机制。",
        "paragraph_briefs": [
          {
            "point": "分析有限孔径下群延迟需求的非单调性特征。",
            "development": "利用P0002的数值分析结果，论证在有限半径R的透镜上，所需群延迟范围并非随入射角 $\\alpha$ 单调增加。解释由于几何投影效应，在掠射角（grazing angles）附近，光线穿过透镜的有效光程差变化率降低，导致所需的相位调制范围反而减小。",
            "source_handles": ["P0002"]
          },
          {
            "point": "确定决定带宽上限的关键角度 $\\alpha^*$。",
            "development": "指出最大群延迟差值 $\\Delta T_{max}$ 出现在某个特定的中间角度 $\\alpha^*$，而非最大视场角 $\\alpha_0$。该角度使得透镜上的群延迟极差（最大值与最小值之差）最大，是决定带宽上限的瓶颈位置。",
            "source_handles": ["P0002"]
          },
          {
            "point": "阐释带宽饱和现象的物理机制。",
            "development": "基于上述非单调性，揭示‘带宽饱和’现象：当工作视场角 $\\alpha_0$ 小于临界角 $\\alpha^*$ 时，增大FOV会压缩带宽；但一旦 $\\alpha_0 > \\alpha^*$，继续增大FOV所引入的新角度对应的群延迟范围小于 $\\alpha^*$ 处的值，因此 $\\Delta T_{max}$ 被锁定，带宽下限停止收紧并趋于饱和。对比两种焦点定义下的饱和趋势，指出该现象修正了‘大视场必然导致带宽急剧下降’的传统直觉。",
            "source_handles": ["P0002"]
          }
        ],
        "conditions_and_limits": "此结论基于标量相位近似和几何光学路径差计算。P0002未提供 $\\alpha^*$ 的解析表达式，仅通过数值模拟展示其存在及对NA的依赖性。综述将据此描述定性趋势，避免给出具体的临界角度公式猜测。",
        "transition": "在确立了色散工程带来的带宽-视场权衡及饱和现象后，本章需转向另一重独立的物理约束：单界面几何像差对视场的根本限制。"
      },
      {
        "unit_id": "U3",
        "substantive_point": "论证单界面几何像差对高NA系统有效视场的根本制约，确立单层结构的物理边界。",
        "ordered_development": "从几何光学角度分析单界面透镜无法校正高阶像差的固有属性。引用具体量化数据说明高NA下低像差视场的微小尺度。批判性地评估将单片超构透镜与多片式复消色差物镜直接比较的不恰当性，确立单层结构无法同时实现大带宽与大视场的最终结论。",
        "paragraph_briefs": [
          {
            "point": "分析单界面几何像差的产生机制。",
            "development": "引用P0001的观点，指出即使色散被完美补偿，单界面透镜仍无法校正彗差、像散等几何像差。解释这是由于缺乏多元件间的轴向距离来平衡不同入射角带来的相位需求差异，导致像差随孔径或视场角的增加迅速增大。",
            "source_handles": ["P0001"]
          },
          {
            "point": "量化高NA下单层结构的有效视场限制。",
            "development": "提供具体量化证据：对于NA=0.5、焦距1mm的单层超构透镜，在可见光范围内，若要求路径延迟误差不超过一个波长，其低像差视场被严格限制在小于5 µm的范围内。论证这意味着即便带宽-视场积允许较大的理论FOV，实际可用的清晰成像区域仍被几何像差严格限制。",
            "source_handles": ["P0001"]
          },
          {
            "point": "批判不恰当的成像质量比较基准。",
            "development": "剖析Kho16等研究中将单片超构透镜与商用多片复消色差物镜进行直接对比的误导性。指出这种比较忽视了单界面几何像差的根本限制，属于‘苹果与橘子’的比较。确立‘单层结构无法同时实现大带宽与大视场’的物理边界，说明任何突破此限制的尝试必须引入多片系统或非局部设计。",
            "source_handles": ["P0001"]
          }
        ],
        "conditions_and_limits": "此限制针对的是单片平面超构透镜。P0001明确指出这是单界面元素的固有属性，多片式复消色差物镜可通过组合透镜校正这些像差，但这已超出本综述对‘单片金属透镜’的核心关注范围，仅作为背景对比提及。",
        "transition": "本章确立了由延迟-带宽积和单界面几何决定的理论天花板。下一章（CH2）将深入微观层面，探讨现有的纳米结构设计机制如何尝试逼近这些界限，以及由此产生的效率权衡。"
      }
    ]
  }
}

